$pdo=Database::connection();
$slug=trim((string)($_GET['empresa']??''));
$stmt=$pdo->prepare('SELECT * FROM tenants WHERE slug=? AND status="active" LIMIT 1');$stmt->execute([$slug]);$tenant=$stmt->fetch();
if(!$tenant){http_response_code(404);exit('Empresa não encontrada.');}
$tenantId=(int)$tenant['id'];if(!TenantFeatures::menu($tenantId)){http_response_code(404);exit('Cardápio não habilitado para esta empresa.');}
$settings=json_decode((string)($tenant['settings']??'{}'),true)?:[];
$tableToken=trim((string)($_GET['mesa']??''));$table=null;
if($tableToken!==''){$s=$pdo->prepare('SELECT * FROM restaurant_tables WHERE tenant_id=? AND qr_token=? AND status<>"inactive" LIMIT 1');$s->execute([$tenantId,$tableToken]);$table=$s->fetch()?:null;if(!$table){http_response_code(404);exit('Mesa não encontrada ou inativa.');}}
$cartKey='public_cart_'.$tenantId;if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];$cart=&$_SESSION[$cartKey];$error=null;$configured=new ConfiguredOrderService();
// Compatibilidade com carrinhos antigos: produto_id => quantidade vira linha configurada sem adicionais.
$needsMigration=false;foreach($cart as$key=>$value){if(!is_array($value)){$needsMigration=true;break;}}if($needsMigration){$legacy=$cart;$cart=[];foreach($legacy as$productId=>$qty){$productId=(int)$productId;$qty=(float)$qty;if($productId<1||$qty<=0)continue;$lineKey=hash('sha256',$productId.':');$cart[$lineKey]=['product_id'=>$productId,'qty'=>$qty,'option_ids'=>[]];}}
$selectedFulfillment=in_array((string)($_POST['fulfillment']??'pickup'),['pickup','delivery'],true)?(string)($_POST['fulfillment']??'pickup'):'pickup';
function flatten_options(mixed $value):array{$out=[];$walk=function($v)use(&$out,&$walk){if(is_array($v)){foreach($v as$x)$walk($x);return;}$id=(int)$v;if($id>0)$out[]=$id;};$walk($value);$out=array_values(array_unique($out));sort($out);return $out;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';
    else{
        $action=(string)($_POST['action']??'');
        if($action==='add'){
            try{$id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$optionIds=flatten_options($_POST['option_ids']??[]);$resolved=$configured->resolveLine($pdo,$tenantId,['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds],false);$lineKey=hash('sha256',$id.':'.implode(',',$resolved['option_ids']));if(isset($cart[$lineKey]))$cart[$lineKey]['qty']=min(99,(float)$cart[$lineKey]['qty']+$qty);else$cart[$lineKey]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$resolved['option_ids']];}catch(Throwable$e){$error=$e->getMessage();}
        }
        elseif($action==='remove')unset($cart[(string)($_POST['line_key']??'')]);
        elseif($action==='clear')$cart=[];
        elseif($action==='checkout'){
            try{$rows=array_values($cart);$order=(new PublicMenuService())->create($tenantId,$rows,(string)($_POST['name']??''),(string)($_POST['phone']??''),(string)($_POST['address']??''),$table?$tableToken:null,$table?'table':$selectedFulfillment);$cart=[];header('Location: '.app_url('pedido.php?t='.rawurlencode($order['public_token'])),true,303);exit;}catch(Throwable$e){$error=$e->getMessage();}
        }
        if($action!=='checkout'&&$error===null){$query=['empresa'=>$slug];if($table)$query['mesa']=$tableToken;header('Location: '.app_url('menu.php?'.http_build_query($query)),true,303);exit;}
    }
}
$c=$pdo->prepare('SELECT * FROM categories WHERE tenant_id=? AND active=1 ORDER BY sort_order,name');$c->execute([$tenantId]);$categories=$c->fetchAll();$p=$pdo->prepare('SELECT p.*,EXISTS(SELECT 1 FROM product_recipes r WHERE r.tenant_id=p.tenant_id AND r.product_id=p.id) has_recipe FROM products p WHERE p.tenant_id=? AND p.active=1 ORDER BY p.category_id,p.name');$p->execute([$tenantId]);$products=$p->fetchAll();
$modifierCatalog=$configured->catalogModifiers($pdo,$tenantId,array_column($products,'id'));
