function m(int$c):string{return 'R$ '.number_format($c/100,2,',','.');}function menu_color(mixed$value,string$fallback):string{$v=strtolower(trim((string)$value));return preg_match('/^#[0-9a-f]{6}$/',$v)?$v:$fallback;}
$deliveryFee=max(0,(int)($settings['delivery_fee_cents']??0));$minimum=max(0,(int)($settings['min_delivery_order_cents']??0));$title=trim((string)($settings['menu_public_title']??''))?:$tenant['name'];$subtitle=trim((string)($settings['menu_subtitle']??''))?:'Peça do seu jeito. Rápido e fácil.';$primary=menu_color($settings['menu_primary_color']??'','#f4b942');$background=menu_color($settings['menu_background_color']??'','#090d14');$surface=menu_color($settings['menu_surface_color']??'','#121925');$text=menu_color($settings['menu_text_color']??'','#f5f7fb');$layout=in_array(($settings['menu_layout']??'cards'),['cards','compact'],true)?(string)$settings['menu_layout']:'cards';$headerStyle=in_array(($settings['menu_header_style']??'gradient'),['gradient','solid','minimal'],true)?(string)$settings['menu_header_style']:'gradient';$showImages=(bool)($settings['menu_show_images']??true);$showSearch=(bool)($settings['menu_show_search']??true);$showBranding=(bool)($settings['menu_show_branding']??true);$logoUrl=trim((string)($settings['menu_logo_url']??''));$coverUrl=trim((string)($settings['menu_cover_url']??''));$whatsapp=preg_replace('/\D+/','',(string)($settings['whatsapp']??''))?:'';$canonical=app_url('menu.php?empresa='.rawurlencode($slug));
