php if($prodModifiers):?><details class="modifier-box" open><summary>Personalize este item</summary><?php foreach($prodModifiers as$mg):$min=max((int)$mg['min_select'],(int)$mg['required']?1:0);$max=max(1,(int)$mg['max_select']);?><div class="modifier-group"><div class="modifier-group-title"><span><?= Security::e($mg['name']) ?><?= $min>0?' *':'' ?></span><span class="modifier-rules"><?= $min>0?'mín. '.$min:'opcional' ?> · máx. <?= $max ?></span></div><div class="modifier-options"><?php foreach($mg['options'] as$opt):?><label class="modifier-option"><span><input type="checkbox" name="option_ids[<?= (int)$mg['id'] ?>][]" value="<?= (int)$opt['id'] ?>"> <?= Security::e($opt['name']) ?></span><strong><?= (int)$opt['price_delta_cents']===0?'incluído':((int)$opt['price_delta_cents']>0?'+ ':'- ').m(abs((int)$opt['price_delta_cents'])) ?></strong></label><?php endforeach;?></div></div><?php endforeach;?></details><?php endif;?></form></div></article><?php endforeach;?></div></section><?php endforeach;?><?php endif;?></section>
<aside class="cart" id="cart"><div class="cart-head"><div><span class="eyebrow"><?= $table?'MESA':'SEU PEDIDO' ?></span><h2><?= $cartCount>0?$cartCount.' '.($cartCount===1?'item':'itens'):'Seu pedido' ?></h2></div><?php if($cartRows):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="clear"><button class="clear">Limpar</button></form><?php endif;?></div><?php if(!$cartRows):?><div class="empty">Adicione produtos para começar.</div><?php else:?><?php foreach($cartRows as$item):?><div class="line"><div><strong><?= Security::e((string)$item['qty']) ?>× <?= Security::e($item['name']) ?></strong><?php if($item['mods']):?><div class="mods"><?= Security::e(implode(' · ',$item['mods'])) ?></div><?php endif;?><small><?= m($item['line']) ?></small></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($item['line_key']) ?>"><button class="remove" aria-label="Remover">×</button></form></div><?php endforeach;?><div class="total"><span>Subtotal</span><strong><?= m($cartTotal) ?></strong></div><form method="post" class="checkout-form" id="checkout"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label>Seu nome<input name="name" required placeholder="Como podemos te chamar?"></label><label>Telefone<input name="phone"<?= $table?'':' required' ?> inputmode="tel" placeholder="(22) 99999-9999"></label><?php if(!$table):?><div class="fulfillment-title">Como você quer receber?</div><div class="fulfillment"><label class="choice"><input type="radio" name="fulfillment" value="pickup"<?= $selectedFulfillment==='pickup'?' checked':'' ?>><span><b>Retirada no local</b><small>Você busca no estabelecimento e apresenta o QR do pedido.</small></span></label><label class="choice"><input type="radio" name="fulfillment" value="delivery"<?= $selectedFulfillment==='delivery'?' checked':'' ?>><span><b>Delivery</b><small>Entregamos no seu endereço<?= $deliveryFee>0?' · '.m($deliveryFee):'' ?>.</small></span></label></div><label id="address-field">Endereço de entrega<textarea name="address" placeholder="Rua, número, bairro e referência"></textarea></label><div id="delivery-info" class="delivery-info"><?php if($minimum>0):?>Pedido mínimo para delivery: <?= m($minimum) ?>. <?php endif;?>A taxa de entrega só é aplicada quando Delivery estiver selecionado.</div><?php else:?><div class="notice">Este pedido será lançado diretamente na <?= Security::e($table['name']) ?>. Pedido de mesa/comanda não precisa de QR de retirada.</div><?php endif;?><button class="checkout"><?= $table?'Enviar pedido para a mesa':'Confirmar pedido' ?></button></form><?php endif;?></aside></div>
<?php if($showBranding):?><footer class="powered">Powered by <b>EventMenu</b></footer><?php endif;?></main><?php if($cartRows):?><a class="mobile-cart" href="#cart"><span>Ver pedido · <?= $cartCount ?> <?= $cartCount===1?'item':'itens' ?></span><strong><?= m($cartTotal) ?></strong></a><?php endif;?><script>const search=document.getElementById('menu-search');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase('pt-BR');document.querySelectorAll('[data-product]').forEach(card=>card.hidden=q!==''&&!card.dataset.search.includes(q));document.querySelectorAll('.section').forEach(section=>section.hidden=![...section.querySelectorAll('[data-product]')].some(card=>!card.hidden))});const choices=document.querySelectorAll('input[name="fulfillment"]'),addressField=document.getElementById('address-field'),deliveryInfo=document.getElementById('delivery-info');function syncFulfillment(){const delivery=document.querySelector('input[name="fulfillment"]:checked')?.value==='delivery';if(addressField){addressField.hidden=!delivery;const ta=addressField.querySelector('textarea');if(ta)ta.required=delivery}if(deliveryInfo)deliveryInfo.hidden=!delivery}choices.forEach(el=>el.addEventListener('change',syncFulfillment));syncFulfillment();document.querySelectorAll('.modifier-group').forEach(group=>{const checks=[...group.querySelectorAll('input[type="checkbox"]')];const rules=group.querySelector('.modifier-rules')?.textContent||'';const match=rules.match(/máx\.\s*(\d+)/);const max=match?parseInt(match[1],10):99;checks.forEach(check=>check.addEventListener('change',()=>{if(checks.filter(c=>c.checked).length>max){check.checked=false;alert('Este grupo permite no máximo '+max+' escolha(s).')}}))});</script></body></html>